// Expected payload (dispatched by ConsultationService::createConsultation when
// the advisory body type === 'external'):
//
// {
//   consultationId, consultationNummer, caseId, caseTitle,
//   adviesinstantie: { id, naam, email, type: 'external' },
//   onderwerp, vraag, uiterlijkeReactiedatum,
//   responseToken,          // 256-bit secure plaintext token (delivered ONCE)
//   responseUrl,            // /apps/dossiq/external/consultations/{token}
//   attachments: [ { documentUuid, fileName } ]
// }
const payload = $input.first().json.body || $input.first().json || {};
if (!payload.adviesinstantie || payload.adviesinstantie.type !== 'external') {
  // Internal advisory body — group notifications are handled by NC IManager.
  return [{ json: { skip: true, reason: 'not-external-body' } }];
}
if (!payload.responseToken || !payload.responseUrl) {
  return [{ json: { skip: true, reason: 'missing-response-token-url' } }];
}
return [{ json: { skip: false, ...payload } }];
